def allocate_cents(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError('total must be an integer')
    if not isinstance(weights, list):
        raise TypeError('weights must be a list')
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError('weights must contain integers')
    if total < 0:
        raise ValueError('total must be nonnegative')
    if not weights:
        raise ValueError('weights must be nonempty')
    if any(weight <= 0 for weight in weights):
        raise ValueError('weights must be positive')
    denominator = sum(weights)
    allocations = []
    remainders = []
    for weight in weights:
        share, remainder = divmod(total * weight, denominator)
        allocations.append(share)
        remainders.append(remainder)
    remaining = total - sum(allocations)
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for index in order[:remaining]:
        allocations[index] += 1
    return allocations

import math

def categorical_loss_grad(logits, labels):
    if not isinstance(logits, list) or not logits:
        raise ValueError("logits must be a nonempty list")
    if not isinstance(labels, list) or len(labels) != len(logits):
        raise ValueError("labels must match the batch")
    if not isinstance(logits[0], list) or len(logits[0]) < 2:
        raise ValueError("at least two classes are required")
    classes = len(logits[0])
    rows = []
    for row in logits:
        if not isinstance(row, list) or len(row) != classes:
            raise ValueError("logits must be rectangular")
        values = []
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("logits must be finite numbers")
            try:
                value = float(value)
            except (OverflowError, ValueError):
                raise ValueError("logit is not representable") from None
            if not math.isfinite(value):
                raise ValueError("logits must be finite")
            values.append(value)
        rows.append(values)
    for label in labels:
        if isinstance(label, bool) or not isinstance(label, int):
            raise ValueError("labels must be integer class indices")
        if not 0 <= label < classes:
            raise ValueError("label is outside the class range")
    n = len(rows)
    loss = 0.0
    gradient = []
    for row, label in zip(rows, labels):
        maximum = max(row)
        exponentials = [math.exp(value - maximum) for value in row]
        total = math.fsum(exponentials)
        # Scale before subtracting: the unscaled gap may overflow even
        # when its contribution to the batch mean is representable.
        loss += (maximum / n - row[label] / n) + math.log(total) / n
        gradient.append([
            (exponentials[j] / total - (1.0 if j == label else 0.0)) / n
            for j in range(classes)
        ])
    return loss, gradient

def check_contract(fn):
    class PortInteger(int):
        pass

    for value in (1, 2, 80, 443, 32768, 65534, 65535, PortInteger(8080)):
        result = fn(value)
        assert isinstance(result, int) and not isinstance(result, bool), (
            "valid port must return an integer", value, result
        )
        assert result == value, ("valid port changed", value, result)

    for value in (0, -1, -(10 ** 40), 65536, 65537, 10 ** 40):
        try:
            fn(value)
        except ValueError:
            pass
        else:
            raise AssertionError(("expected ValueError", value))

    for value in (True, False, None, "80", "", 80.0, 1.0, 65535.0,
                  b"80", [], {}, (), 80 + 0j):
        try:
            fn(value)
        except TypeError:
            pass
        else:
            raise AssertionError(("expected TypeError", value))
